 files=[ROOT/'output/pdf/avocado-mini-spatial-os-design.pdf',ROOT/'docs/avocado-mini-r5/spatial-computer-use-design.md',ROOT/'contracts/avocado-mini-spatial-runtime.json',ROOT/'lib/mini-spatial-workflow.ts',ROOT/'lib/smis-camera.ts',ROOT/'lib/smis-visual-input.ts',ROOT/'systems/rock-star-os/targets/avocado-mini/hardware/spatial-mainboard-plan.json',ROOT/'systems/rock-star-os/targets/avocado-mini/hardware/generate_spatial_floorplan.py',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/stereo_marker_observer.py',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/stereo-calibration.template.json',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/d405_depth_observer.py',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/d405-profile.template.json',ROOT/'public/brand/rockstaros-logo-source.png',ROOT/'docs/avocado-mini-r5/assets/e1-leairr-optical-path.png',ROOT/'docs/avocado-mini-r5/assets/e1-binocular-coverage.png',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/go-bridge-observer.py',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/go-bridge-profile.template.json',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/hand_landmark_observer.py',ROOT/'systems/rock-star-os/targets/avocado-mini/linux/hand-profile.template.json',ROOT/'systems/rock-star-os/targets/avocado-mini/hardware/reference-interface-map.json']
 for folder in ['docs/avocado-mini-r5/factory-development','systems/rock-star-os/targets/avocado-mini/spatial','work/mini-spatial-engineering','systems/rock-star-os/targets/avocado-mini/hardware/cell-power']:
  files.extend(p for p in (ROOT/folder).rglob('*') if p.is_file() and (p.suffix in ['.md','.json','.py','.mjs','.html','.scad','.svg','.kicad_pcb','.kicad_sch','.kicad_pro','.kicad_sym','.kicad_mod','.csv','.txt'] or p.name in ['fp-lib-table','sym-lib-table']) and '__pycache__' not in str(p))
